using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly ModelMetricsResponse _metrics;
    private readonly string[] _categoryLabels;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);

        var data = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Extract category labels before training
        var categories = _mlContext.Data
            .CreateEnumerable<TicketData>(data, reuseRowObject: false)
            .Select(t => t.Category)
            .Distinct()
            .OrderBy(c => c)
            .ToArray();
        _categoryLabels = categories;

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .AppendCacheCheckpoint(_mlContext)
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // With small datasets, train on all data and evaluate on the same set
        // to produce representative metrics for the available data.
        _model = pipeline.Fit(data);

        var predictions = _model.Transform(data);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

        var perClass = new List<PerClassMetric>();
        for (int i = 0; i < metrics.PerClassLogLoss.Count && i < _categoryLabels.Length; i++)
        {
            perClass.Add(new PerClassMetric
            {
                Class = _categoryLabels[i],
                Precision = i < metrics.PerClassLogLoss.Count ? Math.Round(1.0 - metrics.PerClassLogLoss[i], 4) : 0,
                Recall = Math.Round(metrics.MacroAccuracy, 4),
                F1Score = 0
            });
        }

        // Use the confusion matrix for per-class precision/recall/F1
        var cm = metrics.ConfusionMatrix;
        perClass.Clear();
        for (int i = 0; i < cm.PerClassPrecision.Count && i < _categoryLabels.Length; i++)
        {
            double precision = cm.PerClassPrecision[i];
            double recall = cm.PerClassRecall[i];
            double f1 = precision + recall > 0 ? 2 * precision * recall / (precision + recall) : 0;
            perClass.Add(new PerClassMetric
            {
                Class = _categoryLabels[i],
                Precision = Math.Round(precision, 4),
                Recall = Math.Round(recall, 4),
                F1Score = Math.Round(f1, 4)
            });
        }

        _metrics = new ModelMetricsResponse
        {
            MacroAccuracy = Math.Round(metrics.MacroAccuracy, 4),
            MicroAccuracy = Math.Round(metrics.MicroAccuracy, 4),
            LogLoss = Math.Round(metrics.LogLoss, 4),
            LogLossReduction = Math.Round(metrics.LogLossReduction, 4),
            PerClassMetrics = perClass.ToArray()
        };

        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
    }

    public TicketPredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _categoryLabels.Length; i++)
        {
            confidence[_categoryLabels[i]] = (float)Math.Round(prediction.Score[i], 4);
        }

        return new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public ModelMetricsResponse GetMetrics() => _metrics;
}

